const BODY_FUNCTION_OPTIONS = ['유연성', '민첩성', '순발력', '협응력', '근력·근지구력', '심폐지구력', '리듬감', '평형성'];
const TAG_PREFIX = {
  movement: '움직임:',
  bodyFunction: '신체 기능:',
