});

function splitLines(value: string) {
  return value
    .split('\n')
    .map((item) => item.trim())
    .filter(Boolean);
}

function joinLines(value: string[] | null | undefined) {
  return (value ?? []).filter(Boolean).join('\n');
}

function csvToList(value: string) {
  return value
    .split(',')
    .map((item) => item.trim())
    .filter(Boolean);
}

function listToCsvValue(value: string[]) {
  return value.filter(Boolean).join(', ');
}

function toggleOption(list: string[], option: string) {
  const hasOption = list.includes(option);
  if (option === 'ALL') return hasOption ? [] : ['ALL'];
  const withoutAll = list.filter((item) => item !== 'ALL');
  return hasOption ? withoutAll.filter((item) => item !== option) : [...withoutAll, option];
}

function taggedValue(prefix: string, option: string) {
  return `${prefix}${option}`;
}

function selectedTaggedOptions(tags: string, prefix: string) {
  return csvToList(tags)
    .filter((tag) => tag.startsWith(prefix))
    .map((tag) => tag.slice(prefix.length));
}

function updateTaggedOptions(tags: string, prefix: string, nextOptions: string[]) {
  const otherTags = csvToList(tags).filter((tag) => !tag.startsWith(prefix));
  return listToCsvValue([...otherTags, ...nextOptions.map((option) => taggedValue(prefix, option))]);
}

function listToCsv(value: string[] | null | undefined) {
  return (value ?? []).filter(Boolean).join(', ');
}

type QualityReport = {
  status: MaterialStatus;
  score: number;
  grade: 'A' | 'B' | 'C' | 'D';
  thumbnailSource: '세팅 이미지' | '영상 썸네일' | '없음';
  modalReady: boolean;
  detailReady: boolean;
  dashboardCandidates: string[];
  checks: {
    video: boolean;
    setupImage: boolean;
    indoorSpace: boolean;
    target: boolean;
    space: boolean;
    participant: boolean;
    equipment: boolean;
    steps: boolean;
    variations: boolean;
    homeExposure: boolean;
  };
  reasons: string[];
};

function resolveStatus(checks: QualityReport['checks']): MaterialStatus {
  const coreReady = checks.target && checks.space && checks.participant && checks.equipment && checks.steps;
  if (!coreReady) return 'incomplete';

  const operationReady = coreReady;
  if (!operationReady) return 'needs-improvement';

  const hasHomeMedia = checks.video || checks.setupImage;
  const homeReady = operationReady && hasHomeMedia;
  if (homeReady) return 'home-ready';

  const needsProductWork = operationReady && (!checks.variations || !checks.setupImage);
  if (needsProductWork) return 'needs-improvement';

  return 'ready';
}

function buildQualityReport(checks: QualityReport['checks'], displayOrder: number): QualityReport {
  const hasMedia = checks.video || checks.setupImage;
  const weightedChecks = [
    hasMedia,
    checks.target,
    checks.space,
    checks.participant,
    checks.equipment,
    checks.steps,
    checks.variations,
  ];
  const score = Math.round((weightedChecks.filter(Boolean).length / weightedChecks.length) * 100);
  const modalReady =
    (checks.video || checks.setupImage) &&
    checks.target &&
    checks.space &&
    checks.participant &&
    checks.equipment &&
    checks.setupImage &&
    checks.steps;
  const detailReady =
    checks.equipment &&
    checks.setupImage &&
    checks.steps &&
    checks.variations;
  const dashboardCandidates = [
    checks.homeExposure && displayOrder < 100 ? '홈 첫 row 후보' : '',
    checks.indoorSpace ? '실내/교실 row 후보' : '',
    checks.video ? '영상 수업 row 후보' : '',
  ].filter(Boolean);
  const grade: QualityReport['grade'] =
    score >= 90 && modalReady && detailReady && checks.homeExposure
      ? 'A'
      : score >= 75 && checks.steps && checks.equipment
        ? 'B'
        : score >= 55
          ? 'C'
          : 'D';
  return {
    status: resolveStatus(checks),
    score,
    grade,
    thumbnailSource: checks.setupImage ? '세팅 이미지' : checks.video ? '영상 썸네일' : '없음',
    modalReady,
    detailReady,
    dashboardCandidates,
    checks,
    reasons: qualityReasons(checks),
  };
}

function qualityReasons(checks: QualityReport['checks']) {
  const hasMedia = checks.video || checks.setupImage;
  const items: Array<[string, boolean]> = [
    ['영상/세팅 이미지', hasMedia],
    ['대상', checks.target],
    ['공간', checks.space],
    ['인원', checks.participant],
    ['준비물', checks.equipment],
    ['진행 순서', checks.steps],
    ['변형 방법', checks.variations],
    ['홈 노출', checks.homeExposure],
  ];
  return items.map(([label, ok]) => `${label} ${ok ? '있음' : '없음'}`);
}

function missingQualityLabels(checks: QualityReport['checks']) {
  const hasMedia = checks.video || checks.setupImage;
  const items: Array<[string, boolean]> = [
    ['영상/세팅 이미지', hasMedia],
    ['대상', checks.target],
    ['공간', checks.space],
    ['인원', checks.participant],
    ['준비물', checks.equipment],
    ['활동 방법', checks.steps],
    ['변형 방법', checks.variations],
  ];
  return items.filter(([, ok]) => !ok).map(([label]) => label);
}

function qualitySummary(report: QualityReport) {
  const missing = missingQualityLabels(report.checks);
  if (report.status === 'home-ready') {
    return report.checks.homeExposure ? '홈 노출 조건 충족' : '홈 노출 가능, 노출 설정만 확인';
  }
  if (report.status === 'ready') return '운영 자료로 사용 가능';
  if (report.status === 'needs-improvement') {
    return missing.length ? `보강 필요: ${missing.slice(0, 3).join(', ')}` : '홈 노출 전 상품성 확인 필요';
  }
  return missing.length ? `부족: ${missing.slice(0, 4).join(', ')}` : '핵심 정보 확인 필요';
}

function getItemQuality(item: ProgramItem): QualityReport {
  const meta = item.meta;
  const checks = {
    video: Boolean(item.effective.videoUrl),
    setupImage: Boolean(meta?.sm_setup_image_url),
    indoorSpace: parseMasterSpaces(item.effective.space).includes('교실'),
    target: Boolean(item.effective.target),
    space: Boolean(item.effective.space),
    participant: Boolean(getMasterParticipantFormat(meta?.sm_tags ?? [])),
    equipment: item.effective.equipment.length > 0,
    steps: item.effective.steps.length > 0,
    variations: Boolean(meta?.sm_variation_method?.trim()),
    homeExposure: item.effective.publicationStatus === 'featured' || Boolean(meta?.sm_is_hot),
  };
  return buildQualityReport(checks, meta?.sm_display_order ?? item.curriculum.displayOrder ?? 9999);
}

function getFormQuality(form: EditForm): QualityReport {
  const checks = {
    video: Boolean(form.videoUrl.trim()),
    setupImage: Boolean(form.setupImageUrl.trim()),
    indoorSpace: parseMasterSpaces(form.space).includes('교실'),
    target: Boolean(form.target.trim()),
    space: Boolean(form.space.trim()),
    participant: Boolean(getMasterParticipantFormat(csvToList(form.tags))),
    equipment: splitLines(form.equipment).length > 0,
    steps: splitLines(form.steps).length > 0,
    variations: Boolean(form.variations.trim()),
    homeExposure: form.publicationStatus === 'featured',
  };
  return buildQualityReport(checks, 999);
}

function matchesFilter(item: ProgramItem, filter: FilterKey) {
  const quality = getItemQuality(item);
  if (filter === 'all') return true;
  if (filter === 'home-ready') return quality.status === filter;
  if (filter === 'image-needed') return !quality.checks.setupImage;
  return true;
}

function displayOrderOf(item: ProgramItem) {
  return item.meta?.sm_display_order ?? item.curriculum.displayOrder ?? 9999;
}

function sortForFilter(items: ProgramItem[], filter: FilterKey) {
  const qualityWeight = (item: ProgramItem) => missingQualityLabels(getItemQuality(item).checks).length;
  const copy = [...items];
  if (filter === 'home-ready') {
    return copy.sort((a, b) => displayOrderOf(a) - displayOrderOf(b));
  }
  if (filter === 'image-needed') {
    return copy.sort((a, b) => qualityWeight(b) - qualityWeight(a) || displayOrderOf(a) - displayOrderOf(b));
  }
  return copy;
}

function toForm(item: ProgramItem): EditForm {
  const meta = item.meta;
  const overlay = item.overlay;
  return {
    title: overlay?.title || item.curriculum.title,
    coachScript: meta?.sm_coach_script || '',
    target: serializeMasterTags(parseMasterTargets(meta?.sm_grade || '')),
    space: serializeMasterTags(parseMasterSpaces(meta?.sm_space || '')),
    theme: normalizeLessonTheme(meta?.sm_theme || overlay?.main_theme || ''),
    tags: listToCsv(meta?.sm_tags),
    videoUrl: overlay?.video_url || '',
    setupImageUrl: meta?.sm_setup_image_url || '',
    equipment: overlay?.equipment || joinLines(item.curriculum.equipment),
    briefingNotes: resolveAdminBriefingNotes(meta?.sm_briefing_notes),
    steps: overlay?.activity_method || joinLines(item.curriculum.steps),
    variations: resolveAdminVariationMethod(meta?.sm_variation_method),
    publicationStatus: item.effective.publicationStatus,
  };
}

function mergeSavedProgram(
  current: ProgramItem,
  saved: SavedAdminProgram<Partial<OverlayRow>, MetaRow>,
): ProgramItem {
  const overlay = { ...current.overlay, ...saved.overlay } as OverlayRow;
  const meta = saved.meta;
  const target = serializeMasterTags(parseMasterTargets(meta.sm_grade || ''));
  const space = serializeMasterTags(parseMasterSpaces(meta.sm_space || ''));

  return {
    ...current,
    meta,
    overlay,
    effective: {
      ...current.effective,
      title: overlay.title?.trim() || current.curriculum.title,
      videoUrl: overlay.video_url?.trim() || current.curriculum.url,
      target,
      space,
      equipment: overlay.equipment ? splitLines(overlay.equipment) : current.curriculum.equipment,
      steps: overlay.activity_method ? splitLines(overlay.activity_method) : current.curriculum.steps,
      parentNote: meta.sm_parent_note?.trim() || '',
      relatedSpomoveIds: meta.sm_related_spomove_ids ?? [],
    },
  };
}

function resolveSetupImageSrc(url: string) {
  const trimmed = url.trim();
  if (!trimmed) return '';
  if (trimmed.startsWith('http://') || trimmed.startsWith('https://') || trimmed.startsWith('/')) {
    return trimmed;
  }
  try {
    return getPublicUrl(trimmed);
  } catch {
    return trimmed;
  }
}

function storagePathFromPublicUrl(value: string) {
  const text = value.trim();
  if (!text) return '';
  if (!/^https?:\/\//i.test(text)) return text.split('?')[0] ?? '';
  try {
    const url = new URL(text);
    const marker = '/storage/v1/object/public/iiwarmup-files/';
    const markerIndex = url.pathname.indexOf(marker);
    if (markerIndex < 0) return '';
    return decodeURIComponent(url.pathname.slice(markerIndex + marker.length));
  } catch {
    return '';
  }
}

function SetupImageUpload({
  curriculumId,
  value,
  onChange,
  onRemove,
}: {
  curriculumId: number;
  value: string;
  onChange: (next: string) => void;
  onRemove?: () => void;
}) {
  const [uploading, setUploading] = useState(false);
  const previewSrc = resolveSetupImageSrc(value);

  const handleFile = async (file: File) => {
    if (!file.type.startsWith('image/')) {
      toast.error('이미지 파일만 업로드할 수 있습니다.');
      return;
    }
    if (file.size > MAX_SETUP_IMAGE_BYTES) {
      toast.error('이미지는 10MB 이하만 업로드할 수 있습니다.');
      return;
    }

    setUploading(true);
    try {
      const previousPath = storagePathFromPublicUrl(value);
      const optimized = await optimizeToWebP(file, SETUP_IMAGE_OPTIMIZE);
      const path = `spokedu-master/programs/${curriculumId}/setup-${Date.now()}.webp`;
      await uploadToStorage(path, optimized, 'image/webp');
      onChange(withPublicUrlCacheBust(getPublicUrl(path), Date.now()));
      if (previousPath && previousPath !== path) {
        await deleteFromStorage(previousPath).catch(() => undefined);
      }
      const savedKb = Math.max(1, Math.round(optimized.size / 1024));
      toast.success(`세팅 이미지를 업로드했습니다. (${savedKb}KB)`);
    } catch (error) {
      toast.error(error instanceof Error ? error.message : '이미지 업로드에 실패했습니다.');
    } finally {
      setUploading(false);
    }
  };

  return (
    <div className="space-y-2">
      <input
        type="file"
        accept="image/*"
        disabled={uploading}
        className="block w-full text-[12px] font-semibold text-slate-600 file:mr-3 file:rounded-lg file:border-0 file:bg-indigo-50 file:px-3 file:py-2 file:text-[12px] file:font-black file:text-indigo-700 hover:file:bg-indigo-100"
        onChange={async (event) => {
          const file = event.target.files?.[0];
          if (file) await handleFile(file);
          event.target.value = '';
        }}
      />
      {uploading ? (
        <div className="flex items-center gap-2 text-[12px] font-semibold text-slate-500">
          <Loader2 className="h-4 w-4 animate-spin" />
          업로드 중…
        </div>
      ) : null}
      {previewSrc ? (
        <div className="overflow-hidden rounded-lg border border-slate-200 bg-slate-50">
          <img src={previewSrc} alt="초기 교구 세팅 미리보기" className="max-h-64 w-full object-contain" />
          <div className="flex items-center justify-between gap-2 border-t border-slate-200 px-3 py-2">
            <p className="truncate text-[11px] font-semibold text-slate-500">{value}</p>
            <button
              type="button"
              className="shrink-0 text-[11px] font-black text-rose-600"
              onClick={onRemove ?? (() => {
                const path = storagePathFromPublicUrl(value);
                onChange('');
                if (path) void deleteFromStorage(path).catch(() => undefined);
              })}
            >
              제거
            </button>
          </div>
        </div>
      ) : (
        <p className="text-[11px] font-semibold text-slate-400">이미지를 선택하면 자동 업로드됩니다.</p>
      )}
    </div>
  );
}

function spomoveThumbnailPath(presetId: string, ext: string) {
  return `spokedu-master/spomove-thumbnails/${presetId}/thumbnail.${ext}`;
}

function resolveSpomoveThumbnailUrl(path: string | null | undefined, cacheBust?: number) {
  if (!path) return '';
  try {
    return withPublicUrlCacheBust(getPublicUrl(path), cacheBust);
  } catch {
    return '';
  }
}

function liveContentDraft(
  current: Record<string, SpomovePresetContentOverride>,
  presetId: string,
): SpomovePresetContentOverride {
  return current[presetId] ?? normalizeContentDraft(undefined);
}

function formatCatalogTagsForEditor(tags: readonly string[] | undefined) {
  return (tags ?? []).join(', ');
}

function parseCatalogTagsForEditor(value: string) {
  return value.split(',').slice(0, 5);
}

function normalizeContentDraft(value: SpomovePresetContentOverride | undefined): SpomovePresetContentOverride {
  return {
    recommendedCueSeconds: value?.recommendedCueSeconds,
    recommendedCueTiming: value?.recommendedCueTiming,
    displayTitle: value?.displayTitle ?? '',
    shortDescription: value?.shortDescription ?? '',
    variantLabel: value?.variantLabel ?? '',
    catalogTags: value?.catalogTags ?? [],
    isVisible: value?.isVisible ?? true,
    sortOrder: value?.sortOrder,
    coreKeywords: normalizeSpomoveCoreKeywordsList(value?.coreKeywords ?? []),
    activityMethod: value?.activityMethod ?? '',
    activityConcept: value?.activityConcept ?? '',
    movementGuide: normalizeSpomoveMovementGuideDraft(value?.movementGuide),
    movementGuideStatus: value?.movementGuideStatus,
    sourceFingerprint: value?.sourceFingerprint,
    sourceFingerprintVersion: value?.sourceFingerprintVersion,
    sourceReviewedAt: value?.sourceReviewedAt,
  };
}

function contentDraftIsEmpty(value: SpomovePresetContentOverride | undefined) {
  return (
    value?.recommendedCueSeconds == null &&
    value?.recommendedCueTiming == null &&
    !value?.displayTitle?.trim() &&
    !value?.shortDescription?.trim() &&
    !value?.variantLabel?.trim() &&
    !(value?.catalogTags?.length) &&
    !value?.activityMethod?.trim() &&
    !value?.activityConcept?.trim() &&
    !value?.movementGuide &&
    normalizeSpomoveCoreKeywordsList(value?.coreKeywords ?? []).length === 0
  );
}

function isBuiltInGuidePreset(preset: OfficialSpomovePreset) {
  return preset.movementProfileId === 'bodyCueBuiltIn' || preset.movementProfileId === 'diveBuiltIn';
}

function resolvePresetGuideMovement(preset: OfficialSpomovePreset): SpomoveMovementGuideDraft['movement'] {
  if (preset.id === 'dive-standard') return { baseMovement: 'combined', limbRule: 'free' };
  if (isBuiltInGuidePreset(preset)) return null;
  return getPresetMovementSummary(preset)?.officialRecommended ?? preset.recommendedMovement;
}

function getMovementGuideLabel(movement: SpomoveMovementGuideDraft['movement']) {
  if (movement === null) return '화면 지시';
  if (!movement) return '미설정';
  return movementDisplayLabel(movement);
}

function withPresetGuideMovement(
  preset: OfficialSpomovePreset,
  guide: SpomoveMovementGuideDraft | undefined,
): SpomoveMovementGuideDraft {
  return {
    ...guide,
    movement: guide?.movement ?? resolvePresetGuideMovement(preset),
  };
}

function buildMovementGuideStarterDraft(
  preset: OfficialSpomovePreset,
  guide: SpomoveMovementGuideDraft | undefined,
): SpomoveMovementGuideDraft {
  const movement = guide?.movement ?? resolvePresetGuideMovement(preset);
  const movementDefinition =
    movement && movement !== null ? MOVEMENT_REGISTRY[movement.baseMovement] : null;
  const defaultTag: SpomoveFocusTag =
    preset.axis === 'executive'
      ? 'ruleSwitching'
      : preset.axis === 'attention'
        ? 'visualSearch'
        : 'choiceReaction';

  return {
    ...guide,
    movement,
    instruction:
      guide?.instruction ??
      movementDefinition?.instruction ??
      `${preset.description} 화면 신호를 확인하고 정해진 규칙에 맞춰 반응합니다.`,
    coachScript:
      guide?.coachScript ??
      movementDefinition?.teacherCue ??
      '화면을 먼저 보고, 맞는 신호에만 빠르게 반응해요.',
    focusTags: guide?.focusTags?.length ? guide.focusTags : [defaultTag],
    easier:
      guide?.easier ??
      movementDefinition?.easyVariation ??
      '자극 시간을 늘리고 한 가지 규칙만 사용해 천천히 진행합니다.',
    harder:
      guide?.harder ??
      movementDefinition?.hardVariation ??
      '자극 시간을 줄이고 추가 규칙이나 연속 반응을 더해 진행합니다.',
  };
}

function getMovementGuideCompletion(
  preset: OfficialSpomovePreset,
  guide: SpomoveMovementGuideDraft | undefined,
) {
  const requiredFields = ['movement', 'instruction', 'coachScript', 'focusTags', 'easier', 'harder'] as const;
  const issues = validateSpomoveMovementGuideDraft({ draft: guide, preset });
  const missingFields = new Set(issues.map((issue) => issue.field));
  const completeCount = requiredFields.length - missingFields.size;
  const percent = Math.round((completeCount / requiredFields.length) * 100);

  return {
    percent,
    issues,
    completeCount,
    requiredCount: requiredFields.length,
  };
}

type ThinkAssetPackSaveResponse = {
  error?: string;
  issues?: SpomovePublishedGuideSaveIssue[];
  updated_at?: string;
  conflict?: boolean;
  assets_json?: unknown;
};

class ThinkAssetPackConflictError extends Error {
  readonly body: ThinkAssetPackSaveResponse;

  constructor(message: string, body: ThinkAssetPackSaveResponse) {
    super(message);
    this.name = 'ThinkAssetPackConflictError';
    this.body = body;
  }
}

async function saveThinkAssetPack(payload: {
  id: string;
  name: string;
  theme?: string | null;
  assets_json: unknown;
  expected_updated_at?: string | null;
}): Promise<ThinkAssetPackSaveResponse> {
  const res = await fetch('/api/admin/think-asset-pack', {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    credentials: 'same-origin',
    body: JSON.stringify(payload),
  });
  const body = (await res.json().catch(() => ({}))) as ThinkAssetPackSaveResponse;
  if (res.status === 409) {
    throw new ThinkAssetPackConflictError(body.error ?? '다른 관리자가 먼저 저장했습니다.', body);
  }
  if (!res.ok) {
    const issues = normalizeSpomoveGuideSaveIssues(body.issues);
    throw new SpomoveContentSaveError(body.error ?? 'think_asset_packs 저장에 실패했습니다.', issues);
  }
  return body;
}

type SpomoveContentWorkFilter =
  | 'all'
  | 'missingGuide'
  | 'draft'
  | 'published'
  | 'hasIssue'
  | 'briefingReady'
  | 'needsEditorial'
  | 'legacy'
  | 'missingBriefing'
  | 'gapObjective'
  | 'gapTeachingPoints'
  | 'gapInstruction'
  | 'gapFocusTags'
  | 'sourceCurrent'
  | 'sourceChanged'
  | 'sourceUntracked';

const SPOMOVE_CONTENT_WORK_FILTERS: Array<{ id: SpomoveContentWorkFilter; label: string }> = [
  { id: 'all', label: '전체' },
  { id: 'missingGuide', label: '공식 가이드 없음' },
  { id: 'draft', label: 'Draft' },
  { id: 'published', label: 'Published' },
  { id: 'hasIssue', label: '오류' },
];

const SPOMOVE_BRIEFING_READINESS_FILTERS: Array<{ id: SpomoveContentWorkFilter; label: string }> = [
  { id: 'briefingReady', label: 'Briefing Ready' },
  { id: 'needsEditorial', label: 'Needs Editorial' },
  { id: 'legacy', label: 'Legacy' },
  { id: 'missingBriefing', label: 'Missing' },
];

const SPOMOVE_SOURCE_INTEGRITY_FILTERS: Array<{ id: SpomoveContentWorkFilter; label: string }> = [
  { id: 'sourceCurrent', label: 'Source Current' },
  { id: 'sourceChanged', label: 'Review Required' },
  { id: 'sourceUntracked', label: 'Source Untracked' },
];

const SPOMOVE_BRIEFING_GAP_FILTERS: Array<{ id: SpomoveContentWorkFilter; label: string }> = [
  { id: 'gapObjective', label: 'objective 없음' },
  { id: 'gapTeachingPoints', label: 'teachingPoints 없음' },
  { id: 'gapInstruction', label: 'instruction 없음' },
  { id: 'gapFocusTags', label: 'focusTags 없음' },
];

const BRIEFING_READINESS_LABELS: Record<SpomoveBriefingReadiness, string> = {
  ready: 'Briefing Ready',
  needsEditorial: 'Needs Editorial',
  legacy: 'Legacy',
  missing: 'Missing',
};

const SOURCE_INTEGRITY_LABELS: Record<SpomoveGuideSourceIntegrityStatus, string> = {
  current: 'Source Current',
  changed: 'Source Changed',
  untracked: 'Source Untracked',
};

function matchesSpomoveContentWorkFilter({
  filter,
  preset,
  draft,
  issuePresetIds,
}: {
  filter: SpomoveContentWorkFilter;
  preset: OfficialSpomovePreset;
  draft: SpomovePresetContentOverride;
  issuePresetIds: Set<string>;
}): boolean {
  if (filter === 'all') return true;
  if (filter === 'hasIssue') return issuePresetIds.has(preset.id);
  if (filter === 'missingGuide') return !draft.movementGuide;
  if (filter === 'draft' || filter === 'published') return draft.movementGuideStatus === filter;

  const { readiness, gaps } = resolveSpomoveBriefingReadiness({
    preset,
    contentOverride: draft,
  });
  if (filter === 'briefingReady') return readiness === 'ready';
  if (filter === 'needsEditorial') return readiness === 'needsEditorial';
  if (filter === 'legacy') return readiness === 'legacy';
  if (filter === 'missingBriefing') return readiness === 'missing';
  if (filter === 'gapObjective') return gaps.missingObjective;
  if (filter === 'gapTeachingPoints') return gaps.missingTeachingPoints;
  if (filter === 'gapInstruction') return gaps.missingInstruction;
  if (filter === 'gapFocusTags') return gaps.missingFocusTags;

  const source = resolveSpomoveGuideSourceIntegrity({
    preset,
    contentOverride: draft,
  });
  if (filter === 'sourceCurrent') return source.status === 'current';
  if (filter === 'sourceChanged') return source.status === 'changed';
  if (filter === 'sourceUntracked') return source.status === 'untracked';
  return true;
}

function isSpomoveGuideSaveIssue(value: unknown): value is SpomovePublishedGuideSaveIssue {
  if (!value || typeof value !== 'object') return false;
  const issue = value as Record<string, unknown>;
  return (
    typeof issue.presetId === 'string' &&
    typeof issue.field === 'string' &&
    typeof issue.code === 'string' &&
    Array.isArray(issue.path) &&
    typeof issue.message === 'string'
  );
}

function normalizeSpomoveGuideSaveIssues(value: unknown): SpomovePublishedGuideSaveIssue[] {
  if (!Array.isArray(value)) return [];
  return value.filter(isSpomoveGuideSaveIssue);
}

class SpomoveContentSaveError extends Error {
  readonly issues: SpomovePublishedGuideSaveIssue[];

  constructor(message: string, issues: SpomovePublishedGuideSaveIssue[]) {
    super(message);
    this.name = 'SpomoveContentSaveError';
    this.issues = issues;
  }
}

function patchCoreKeywordAxis(
  current: string[] | undefined,
  key: keyof SpomoveCoreKeywords,
  value: string | null,
): string[] {
  const parsed = parseSpomoveCoreKeywordsOverride(current);
  const next: Partial<SpomoveCoreKeywords> = { ...parsed };
  if (key === 'startPosition') {
    if (!value) delete next.startPosition;
    else next.startPosition = value as SpomoveCoreKeywords['startPosition'];
  } else if (key === 'participation') {
    if (!value) delete next.participation;
    else next.participation = value as SpomoveCoreKeywords['participation'];
  } else {
    if (!value) delete next.difficulty;
    else next.difficulty = value as SpomoveCoreKeywords['difficulty'];
  }
  if (next.startPosition && next.participation && next.difficulty) {
    return serializeSpomoveCoreKeywords({
      startPosition: next.startPosition,
      participation: next.participation,
      difficulty: next.difficulty,
    });
  }
  return normalizeSpomoveCoreKeywordsList([
    next.startPosition,
    next.participation,
    next.difficulty,
  ].filter(Boolean) as string[]);
}

