        <div className="flex shrink-0 items-center justify-between gap-2 border-t border-slate-100 px-5 py-3">
          <button type="button" onClick={onDelete} disabled={!saved || saving || deleting}
            className="inline-flex h-9 items-center justify-center rounded-lg border border-slate-200 px-3 text-[12px] font-black text-rose-600 hover:bg-rose-50 disabled:opacity-40">
            {deleting ? <Loader2 size={13} className="mr-1 animate-spin" /> : null}삭제
          </button>
          <div className="flex items-center gap-2">
            <button type="button" onClick={onClose} className="inline-flex h-9 items-center justify-center rounded-lg border border-slate-200 bg-white px-3 text-[12px] font-black text-slate-600">닫기</button>
            <button type="button" onClick={onSave} disabled={!dirty || saving || deleting}
              className="spm-btn-primary inline-flex h-9 items-center justify-center rounded-[10px] px-4 text-[12px] font-black focus-visible:outline-none disabled:opacity-40">
              {saving ? <Loader2 size={13} className="mr-1 animate-spin" /> : null}저장
            </button>
          </div>
        </div>
      </div>
    </div>
  );
}

function useSpomoveContentData() {
  const [contentMap, setContentMap] = useState<Record<string, SpomovePresetContentOverride>>({});
  const contentRef = useRef(contentMap);
  contentRef.current = contentMap;
  const packUpdatedAtRef = useRef<string | null>(null);
  const [draftMap, setDraftMap] = useState<Record<string, SpomovePresetContentOverride>>({});
  const [loading, setLoading] = useState(true);
  const [savingPresetId, setSavingPresetId] = useState<string | null>(null);
  const [deletingPresetId, setDeletingPresetId] = useState<string | null>(null);
  const [error, setError] = useState<string | null>(null);
  const [saveIssues, setSaveIssues] = useState<SpomovePublishedGuideSaveIssue[]>([]);

  const load = useCallback(async () => {
    setLoading(true);
    setError(null);
    try {
      const supabase = getSupabaseBrowserClient();
      const { data, error: loadError } = await supabase
        .from('think_asset_packs')
        .select('assets_json, updated_at')
        .eq('id', SPOMOVE_CONTENT_PACK_ID)
        .maybeSingle();
      if (loadError && loadError.code !== 'PGRST116') throw loadError;
      const next = normalizeSpomoveContentMap(data?.assets_json);
      packUpdatedAtRef.current = (data?.updated_at as string | undefined) ?? null;
      setContentMap(next);
      contentRef.current = next;
      setDraftMap(next);
    } catch (loadError) {
      setError(loadError instanceof Error ? loadError.message : 'SPOMOVE 설명을 불러오지 못했습니다.');
    } finally {
      setLoading(false);
    }
  }, []);

  useEffect(() => { void load(); }, [load]);

  const persist = useCallback(async (next: Record<string, SpomovePresetContentOverride>) => {
    try {
      const body = await saveThinkAssetPack({
        id: SPOMOVE_CONTENT_PACK_ID,
        name: SPOMOVE_CONTENT_PACK_NAME,
        theme: 'spomove',
        assets_json: { schemaVersion: 2, content: next } satisfies SpomoveContentAssetsJson,
        expected_updated_at: packUpdatedAtRef.current,
      });
      packUpdatedAtRef.current = body.updated_at ?? packUpdatedAtRef.current;
      setContentMap(next);
      contentRef.current = next;
      setDraftMap(next);
      setSaveIssues([]);
    } catch (saveError) {
      if (saveError instanceof ThinkAssetPackConflictError) {
        const serverMap = normalizeSpomoveContentMap(saveError.body.assets_json);
        setContentMap(serverMap);
        contentRef.current = serverMap;
        packUpdatedAtRef.current = saveError.body.updated_at ?? packUpdatedAtRef.current;
      }
      throw saveError;
    }
  }, []);

  const updateDraft = useCallback((presetId: string, patch: Partial<SpomovePresetContentOverride>) => {
    setDraftMap((current) => ({
      ...current,
      [presetId]: { ...liveContentDraft(current, presetId), ...patch },
    }));
  }, []);

  const updateMovementGuide = useCallback((presetId: string, patch: Partial<SpomoveMovementGuideDraft>) => {
    setDraftMap((current) => {
      const currentDraft = liveContentDraft(current, presetId);
      return {
        ...current,
        [presetId]: {
          ...currentDraft,
          movementGuide: { ...currentDraft.movementGuide, ...patch },
        },
      };
    });
  }, []);

  const saveContent = useCallback(async (presetId: string) => {
    const draft = normalizeContentDraft(draftMap[presetId]);
    const previous = contentRef.current[presetId];
    const preset = findOfficialSpomovePreset(presetId);
    let nextEntry: SpomovePresetContentOverride = {
      recommendedCueSeconds: draft.recommendedCueSeconds,
      recommendedCueTiming: draft.recommendedCueTiming,
      displayTitle: draft.displayTitle?.trim() ?? '',
      shortDescription: draft.shortDescription?.trim() ?? '',
      variantLabel: draft.variantLabel?.trim() ?? '',
      catalogTags: draft.catalogTags?.map((tag) => tag.trim()).filter(Boolean).slice(0, 5) ?? [],
      isVisible: draft.isVisible !== false,
      sortOrder: previous?.sortOrder,
      coreKeywords: normalizeSpomoveCoreKeywordsList(draft.coreKeywords ?? []),
      activityMethod: draft.activityMethod?.trim() ?? '',
      activityConcept: draft.activityConcept?.trim() ?? '',
      movementGuide: draft.movementGuide,
      movementGuideStatus: draft.movementGuideStatus,
    };
    if (draft.movementGuideStatus === 'published' && preset) {
      nextEntry = withPublishedSourceBaseline(preset, nextEntry);
    } else {
      nextEntry = preserveSourceBaselineFields(previous, nextEntry);
    }
    const next = { ...contentRef.current };
    if (contentDraftIsEmpty(nextEntry)) delete next[presetId];
    else next[presetId] = nextEntry;
    setSavingPresetId(presetId);
    setError(null);
    setSaveIssues([]);
    try {
      await persist(next);
      toast.success('SPOMOVE 설명을 저장했습니다.');
    } catch (saveError) {
      const message = saveError instanceof Error ? saveError.message : 'SPOMOVE 설명 저장에 실패했습니다.';
      setError(message);
      setSaveIssues(saveError instanceof SpomoveContentSaveError ? saveError.issues : []);
      toast.error(message);
    } finally {
      setSavingPresetId(null);
    }
  }, [draftMap, persist]);

  const deleteContent = useCallback(async (presetId: string) => {
    if (!contentRef.current[presetId]) return;
    const next = { ...contentRef.current };
    delete next[presetId];
    setDeletingPresetId(presetId);
    setError(null);
    setSaveIssues([]);
    try {
      await persist(next);
      toast.success('SPOMOVE 설명을 삭제했습니다.');
    } catch (deleteError) {
      const message = deleteError instanceof Error ? deleteError.message : 'SPOMOVE 설명 삭제에 실패했습니다.';
      setError(message);
      setSaveIssues(deleteError instanceof SpomoveContentSaveError ? deleteError.issues : []);
      toast.error(message);
    } finally {
      setDeletingPresetId(null);
    }
  }, [persist]);

  return {
    contentMap, draftMap, loading, savingPresetId, deletingPresetId, error, saveIssues,
    updateDraft, updateMovementGuide, saveContent, deleteContent,
  };
}

function SpomoveCatalogManager() {
  const {
    contentMap, draftMap, loading, savingPresetId, deletingPresetId, error, saveIssues,
    updateDraft, updateMovementGuide, saveContent, deleteContent,
  } = useSpomoveContentData();
  const [editingPresetId, setEditingPresetId] = useState<string | null>(null);
  const [modalTab, setModalTab] = useState<'guide' | 'card' | 'advanced'>('guide');

  return (
    <>
    <main className="min-h-[calc(100dvh-73px)] bg-slate-50 p-5">
      <div className="mb-5">
        <h2 className="text-xl font-black">공식 SPOMOVE 프리셋</h2>
        <p className="mt-1 text-sm font-semibold text-slate-500">카드를 클릭하면 설명과 가이드를 편집할 수 있습니다.</p>
        {error && <p className="mt-2 rounded-lg border border-rose-100 bg-rose-50 px-3 py-2 text-[12px] font-bold text-rose-700">{error}</p>}
      </div>
      {loading ? (
        <div className="flex justify-center py-16"><div className="h-8 w-8 animate-spin rounded-full border-2 border-indigo-500 border-t-transparent" /></div>
      ) : (
        <div className="space-y-4">
          {SPOMOVE_GROUP_OPTIONS.map((group) => {
            const presets = sortSpomovePresetsByCatalogOrder(
              ADMIN_SPOMOVE_LIBRARY.filter((preset) => preset.programGroup === group.key),
            );
            return (
              <section key={group.key} className="rounded-2xl border border-slate-200 bg-slate-50 p-4">
                <div className="mb-3 flex items-center justify-between gap-3">
                  <h3 className="text-[15px] font-black text-slate-950">{group.label}</h3>
                  <span className="rounded-full bg-white px-2.5 py-1 text-[11px] font-black text-slate-600 shadow-sm">{presets.length}개</span>
                </div>
                <div className="grid gap-3 sm:grid-cols-2 xl:grid-cols-3 2xl:grid-cols-4">
                  {presets.map((preset) => {
                    const display = getSpomovePresetDisplayModel(preset);
                    const draft = normalizeContentDraft(draftMap[preset.id]);
                    const briefing = resolveSpomoveBriefingReadiness({ preset, contentOverride: draft });
                    const sourceIntegrity = resolveSpomoveGuideSourceIntegrity({ preset, contentOverride: draft });
                    return (
                      <button
                        key={preset.id}
                        type="button"
                        onClick={() => { setEditingPresetId(preset.id); setModalTab('guide'); }}
                        className="rounded-2xl border border-slate-200 bg-white p-4 text-left shadow-sm transition-colors hover:border-indigo-300 hover:shadow-md"
                      >
                        <div className="flex items-start justify-between gap-3">
                          <div>
                            <p className="text-[11px] font-black text-indigo-600">{display.axisLabel}</p>
                            <h4 className="mt-1 text-base font-black text-slate-950">{display.displayTitle}</h4>
                          </div>
                          <span className="shrink-0 rounded-full bg-slate-100 px-2 py-1 text-[10px] font-black text-slate-600">{display.programLabel}</span>
                        </div>
                        <p className="mt-2 text-xs font-semibold text-slate-500">{display.settingLabel}</p>
                        <div className="mt-2 flex flex-wrap gap-1.5">
                          {preset.settingChips.slice(0, 4).map((chip) => (
                            <span key={chip} className="rounded-full border border-slate-200 px-2 py-1 text-[10px] font-bold text-slate-500">{chip}</span>
                          ))}
                        </div>
                        <div className="mt-3 flex flex-wrap gap-1">
                          <span className={`rounded-full px-2 py-0.5 text-[10px] font-black ${briefing.readiness === 'ready' ? 'bg-emerald-50 text-emerald-700' : briefing.readiness === 'needsEditorial' ? 'bg-amber-50 text-amber-700' : briefing.readiness === 'legacy' ? 'bg-blue-50 text-blue-700' : 'bg-slate-100 text-slate-500'}`}>
                            {BRIEFING_READINESS_LABELS[briefing.readiness]}
                          </span>
                          {sourceIntegrity.status === 'changed' && (
                            <span className="rounded-full bg-orange-50 px-2 py-0.5 text-[10px] font-black text-orange-800">Source Changed</span>
                          )}
                        </div>
                      </button>
                    );
                  })}
                </div>
              </section>
            );
          })}
        </div>
      )}
    </main>
    {editingPresetId != null && (() => {
      const preset = ADMIN_SPOMOVE_LIBRARY.find((p) => p.id === editingPresetId);
      if (!preset) return null;
      const draft = liveContentDraft(draftMap, editingPresetId);
      const saved = contentMap[editingPresetId];
      const sourceIntegrity = resolveSpomoveGuideSourceIntegrity({ preset, contentOverride: draft });
      return (
        <SpomoveEditModal
          key={preset.id}
          preset={preset}
          draft={draft}
          saved={saved}
          saving={savingPresetId === editingPresetId}
          deleting={deletingPresetId === editingPresetId}
          tab={modalTab}
          saveIssues={saveIssues}
          sourceIntegrity={sourceIntegrity}
          onTabChange={setModalTab}
          onUpdateDraft={(patch) => updateDraft(editingPresetId, patch)}
          onUpdateMovementGuide={(patch) => updateMovementGuide(editingPresetId, patch)}
          onSave={() => { void saveContent(editingPresetId); }}
          onDelete={() => { void deleteContent(editingPresetId).then(() => setEditingPresetId(null)); }}
          onClose={() => setEditingPresetId(null)}
        />
      );
    })()}
    </>
  );
}

function SpomoveContentManager() {
  const [contentMap, setContentMap] = useState<Record<string, SpomovePresetContentOverride>>({});
  const contentRef = useRef(contentMap);
  contentRef.current = contentMap;
  const packUpdatedAtRef = useRef<string | null>(null);
  const [draftMap, setDraftMap] = useState<Record<string, SpomovePresetContentOverride>>({});
  const [loading, setLoading] = useState(true);
  const [savingPresetId, setSavingPresetId] = useState<string | null>(null);
  const [deletingPresetId, setDeletingPresetId] = useState<string | null>(null);
  const [error, setError] = useState<string | null>(null);
  const [saveIssues, setSaveIssues] = useState<SpomovePublishedGuideSaveIssue[]>([]);
  const [workFilter, setWorkFilter] = useState<SpomoveContentWorkFilter>('all');
  const [searchQuery, setSearchQuery] = useState('');
  const [editingPresetId, setEditingPresetId] = useState<string | null>(null);
  const [, setExpandedPresetId] = useState<string | null>(null);
  const [modalTab, setModalTab] = useState<'guide' | 'card' | 'advanced'>('guide');

  const load = useCallback(async () => {
    setLoading(true);
    setError(null);
    try {
      const supabase = getSupabaseBrowserClient();
      const { data, error: loadError } = await supabase
        .from('think_asset_packs')
        .select('assets_json, updated_at')
        .eq('id', SPOMOVE_CONTENT_PACK_ID)
        .maybeSingle();

      if (loadError && loadError.code !== 'PGRST116') throw loadError;

      const next = normalizeSpomoveContentMap(data?.assets_json);
      packUpdatedAtRef.current = (data?.updated_at as string | undefined) ?? null;
      setContentMap(next);
      contentRef.current = next;
      setDraftMap(next);
    } catch (loadError) {
      setError(loadError instanceof Error ? loadError.message : 'SPOMOVE 설명을 불러오지 못했습니다.');
    } finally {
      setLoading(false);
    }
  }, []);

  useEffect(() => {
    void load();
  }, [load]);

  const persist = useCallback(async (next: Record<string, SpomovePresetContentOverride>) => {
    try {
      const body = await saveThinkAssetPack({
        id: SPOMOVE_CONTENT_PACK_ID,
        name: SPOMOVE_CONTENT_PACK_NAME,
        theme: 'spomove',
        assets_json: { schemaVersion: 2, content: next } satisfies SpomoveContentAssetsJson,
        expected_updated_at: packUpdatedAtRef.current,
      });
      packUpdatedAtRef.current = body.updated_at ?? packUpdatedAtRef.current;
      setContentMap(next);
      contentRef.current = next;
      setDraftMap(next);
      setSaveIssues([]);
    } catch (saveError) {
      if (saveError instanceof ThinkAssetPackConflictError) {
        const serverMap = normalizeSpomoveContentMap(saveError.body.assets_json);
        setContentMap(serverMap);
        contentRef.current = serverMap;
        packUpdatedAtRef.current = saveError.body.updated_at ?? packUpdatedAtRef.current;
      }
      throw saveError;
    }
  }, []);

  const updateDraft = (presetId: string, patch: Partial<SpomovePresetContentOverride>) => {
    setDraftMap((current) => ({
      ...current,
      [presetId]: {
        ...liveContentDraft(current, presetId),
        ...patch,
      },
    }));
  };

  const updateMovementGuide = (
    presetId: string,
    patch: Partial<SpomoveMovementGuideDraft>,
  ) => {
    setDraftMap((current) => {
      const currentDraft = liveContentDraft(current, presetId);
      return {
        ...current,
        [presetId]: {
          ...currentDraft,
          movementGuide: {
            ...currentDraft.movementGuide,
            ...patch,
          },
        },
      };
    });
  };

  const saveContent = useCallback(async (presetId: string) => {
    const draft = normalizeContentDraft(draftMap[presetId]);
    const previous = contentRef.current[presetId];
    const preset = findOfficialSpomovePreset(presetId);
    let nextEntry: SpomovePresetContentOverride = {
      recommendedCueSeconds: draft.recommendedCueSeconds,
      recommendedCueTiming: draft.recommendedCueTiming,
      displayTitle: draft.displayTitle?.trim() ?? '',
      shortDescription: draft.shortDescription?.trim() ?? '',
      variantLabel: draft.variantLabel?.trim() ?? '',
      catalogTags: draft.catalogTags?.map((tag) => tag.trim()).filter(Boolean).slice(0, 5) ?? [],
      isVisible: draft.isVisible !== false,
      sortOrder: previous?.sortOrder,
      coreKeywords: normalizeSpomoveCoreKeywordsList(draft.coreKeywords ?? []),
      activityMethod: draft.activityMethod?.trim() ?? '',
      activityConcept: draft.activityConcept?.trim() ?? '',
      movementGuide: draft.movementGuide,
      movementGuideStatus: draft.movementGuideStatus,
    };
    // Draft save keeps baseline; Published confirm refreshes fingerprint.
    if (draft.movementGuideStatus === 'published' && preset) {
      nextEntry = withPublishedSourceBaseline(preset, nextEntry);
    } else {
      nextEntry = preserveSourceBaselineFields(previous, nextEntry);
    }
    const next = { ...contentRef.current };
    if (contentDraftIsEmpty(nextEntry)) delete next[presetId];
    else next[presetId] = nextEntry;

    setSavingPresetId(presetId);
    setError(null);
    setSaveIssues([]);
    try {
      await persist(next);
      toast.success('SPOMOVE 설명을 저장했습니다.');
    } catch (saveError) {
      const message = saveError instanceof Error ? saveError.message : 'SPOMOVE 설명 저장에 실패했습니다.';
      setError(message);
      setSaveIssues(saveError instanceof SpomoveContentSaveError ? saveError.issues : []);
      toast.error(message);
    } finally {
      setSavingPresetId(null);
    }
  }, [draftMap, persist]);

  const deleteContent = useCallback(async (presetId: string) => {
    if (!contentRef.current[presetId]) return;
    const next = { ...contentRef.current };
    delete next[presetId];
    setDeletingPresetId(presetId);
    setError(null);
    setSaveIssues([]);
    try {
      await persist(next);
      toast.success('SPOMOVE 설명을 삭제했습니다.');
    } catch (deleteError) {
      const message = deleteError instanceof Error ? deleteError.message : 'SPOMOVE 설명 삭제에 실패했습니다.';
      setError(message);
      setSaveIssues(deleteError instanceof SpomoveContentSaveError ? deleteError.issues : []);
      toast.error(message);
    } finally {
      setDeletingPresetId(null);
    }
  }, [persist]);

  const savedCount = Object.keys(contentMap).length;
  const issuePresetCount = new Set(saveIssues.map((issue) => issue.presetId)).size;
  const issuePresetIds = useMemo(
    () => new Set(saveIssues.map((issue) => issue.presetId)),
    [saveIssues],
  );
  const matchesWorkFilter = useCallback(
    (presetId: string) => {
      const preset = ADMIN_SPOMOVE_LIBRARY.find((item) => item.id === presetId);
      if (!preset) return false;
      const draft = normalizeContentDraft(draftMap[presetId]);
      return matchesSpomoveContentWorkFilter({
        filter: workFilter,
        preset,
        draft,
        issuePresetIds,
      });
    },
    [draftMap, issuePresetIds, workFilter],
  );
  const visibleContentPresets = useMemo(
    () => ADMIN_SPOMOVE_LIBRARY.filter((preset) => {
      if (!matchesWorkFilter(preset.id)) return false;
      const q = searchQuery.trim().toLowerCase();
      if (!q) return true;
      const draft = normalizeContentDraft(draftMap[preset.id]);
      return [preset.id, preset.title, preset.programTitle, draft.displayTitle, draft.variantLabel, ...(draft.catalogTags ?? [])]
        .filter(Boolean).join(' ').toLowerCase().includes(q);
    }),
    [draftMap, matchesWorkFilter, searchQuery],
  );
  const workFilterCounts = useMemo(() => {
    const allFilters = [
      ...SPOMOVE_CONTENT_WORK_FILTERS,
      ...SPOMOVE_BRIEFING_READINESS_FILTERS,
      ...SPOMOVE_SOURCE_INTEGRITY_FILTERS,
      ...SPOMOVE_BRIEFING_GAP_FILTERS,
    ];
    return allFilters.reduce<Record<SpomoveContentWorkFilter, number>>(
      (counts, filter) => {
        counts[filter.id] = ADMIN_SPOMOVE_LIBRARY.filter((preset) =>
          matchesSpomoveContentWorkFilter({
            filter: filter.id,
            preset,
            draft: normalizeContentDraft(draftMap[preset.id]),
            issuePresetIds,
          }),
        ).length;
        return counts;
      },
      {
        all: 0,
        missingGuide: 0,
        draft: 0,
        published: 0,
        hasIssue: 0,
        briefingReady: 0,
        needsEditorial: 0,
        legacy: 0,
        missingBriefing: 0,
        sourceCurrent: 0,
        sourceChanged: 0,
        sourceUntracked: 0,
        gapObjective: 0,
        gapTeachingPoints: 0,
        gapInstruction: 0,
        gapFocusTags: 0,
      },
    );
  }, [draftMap, issuePresetIds]);
  const guideCompletionSummary = useMemo(() => {
    let readyForReview = 0;
    let published = 0;
    let needsWork = 0;

    ADMIN_SPOMOVE_LIBRARY.forEach((preset) => {
      const draft = normalizeContentDraft(draftMap[preset.id]);
      const completion = getMovementGuideCompletion(preset, draft.movementGuide);
      if (draft.movementGuideStatus === 'published') published += 1;
      if (completion.issues.length === 0 && draft.movementGuideStatus !== 'published') readyForReview += 1;
      if (completion.issues.length > 0) needsWork += 1;
    });

    return { readyForReview, published, needsWork };
  }, [draftMap]);
  const briefingReadinessSummary = useMemo(() => {
    const counts: Record<SpomoveBriefingReadiness, number> = {
      ready: 0,
      needsEditorial: 0,
      legacy: 0,
      missing: 0,
    };
    ADMIN_SPOMOVE_LIBRARY.forEach((preset) => {
      const draft = normalizeContentDraft(draftMap[preset.id]);
      const { readiness } = resolveSpomoveBriefingReadiness({
        preset,
        contentOverride: draft,
      });
      counts[readiness] += 1;
    });
    return counts;
  }, [draftMap]);
  const sourceIntegritySummary = useMemo(() => {
    const counts: Record<SpomoveGuideSourceIntegrityStatus, number> = {
      current: 0,
      changed: 0,
      untracked: 0,
    };
    ADMIN_SPOMOVE_LIBRARY.forEach((preset) => {
      const draft = normalizeContentDraft(draftMap[preset.id]);
      const { status } = resolveSpomoveGuideSourceIntegrity({
        preset,
        contentOverride: draft,
      });
      counts[status] += 1;
    });
    return counts;
  }, [draftMap]);
  const visiblePresetCount = visibleContentPresets.length;
  const fillVisibleStarterDrafts = useCallback(() => {
    if (visibleContentPresets.length === 0) {
      toast.error('현재 필터에 초안을 채울 프리셋이 없습니다.');
      return;
    }

    setDraftMap((current) => {
      const next = { ...current };
      visibleContentPresets.forEach((preset) => {
        const currentDraft = normalizeContentDraft(next[preset.id]);
        next[preset.id] = {
          ...currentDraft,
          movementGuide: buildMovementGuideStarterDraft(preset, currentDraft.movementGuide),
          movementGuideStatus: currentDraft.movementGuideStatus ?? 'draft',
        };
      });
      return next;
    });
    setSaveIssues([]);
    toast.success(`${visibleContentPresets.length}개 프리셋의 가이드 초안을 채웠습니다. 검토 후 저장하세요.`);
  }, [visibleContentPresets]);

  return (
    <>
    <main className="min-h-[calc(100dvh-73px)] bg-slate-50 p-4 sm:p-6">
      <div className="mx-auto max-w-[1500px] space-y-5">
        <section className="rounded-xl border border-slate-200 bg-white p-5 shadow-sm">
          <div className="flex flex-col gap-3 sm:flex-row sm:items-start sm:justify-between">
            <div>
              <p className="text-[11px] font-black uppercase tracking-[0.12em] text-indigo-600">SPOMOVE content</p>
              <h2 className="mt-1 text-[18px] font-black text-slate-950">SPOMOVE 공식 설명</h2>
              <p className="mt-1 text-[12px] font-semibold leading-5 text-slate-500">
                가이드 모달의 핵심 키워드(시작 위치·참여 인원·난이도), 활동방법, 활동 개념을 프리셋별로 수정합니다.
              </p>
            </div>
            <button
              type="button"
              onClick={() => void load()}
              disabled={loading}
              className="inline-flex h-10 shrink-0 items-center justify-center gap-2 rounded-lg border border-slate-200 bg-white px-4 text-[12px] font-black text-slate-700 disabled:opacity-50"
            >
              <RefreshCw size={14} className={loading ? 'animate-spin' : ''} />
              새로고침
            </button>
          </div>
          <div className="mt-4 grid gap-2 sm:grid-cols-3">
            <div className="rounded-lg bg-slate-50 p-3">
              <p className="text-[10px] font-black text-slate-500">공식 프리셋</p>
              <p className="mt-1 text-[18px] font-black text-slate-950">{ADMIN_SPOMOVE_LIBRARY.length}개</p>
            </div>
            <div className="rounded-lg bg-indigo-50 p-3">
              <p className="text-[10px] font-black text-indigo-600">수기 수정</p>
              <p className="mt-1 text-[18px] font-black text-indigo-900">{savedCount}개</p>
            </div>
            <div className="rounded-lg bg-emerald-50 p-3">
              <p className="text-[10px] font-black text-emerald-700">저장 위치</p>
              <p className="mt-1 text-[12px] font-black text-emerald-900">think_asset_packs</p>
            </div>
          </div>
          <div className="mt-2 grid gap-2 sm:grid-cols-3">
            <div className="rounded-lg border border-emerald-100 bg-emerald-50 p-3">
              <p className="text-[10px] font-black text-emerald-700">Published</p>
              <p className="mt-1 text-[18px] font-black text-emerald-950">{guideCompletionSummary.published}개</p>
            </div>
            <div className="rounded-lg border border-indigo-100 bg-indigo-50 p-3">
              <p className="text-[10px] font-black text-indigo-700">검토 후 게시 가능</p>
              <p className="mt-1 text-[18px] font-black text-indigo-950">{guideCompletionSummary.readyForReview}개</p>
            </div>
            <div className="rounded-lg border border-amber-100 bg-amber-50 p-3">
              <p className="text-[10px] font-black text-amber-700">필수값 보완 필요</p>
              <p className="mt-1 text-[18px] font-black text-amber-950">{guideCompletionSummary.needsWork}개</p>
            </div>
          </div>
          <div className="mt-2 grid gap-2 sm:grid-cols-2 lg:grid-cols-5">
            <div className="rounded-lg border border-slate-200 bg-slate-50 p-3">
              <p className="text-[10px] font-black text-slate-500">전체 공개 활동</p>
              <p className="mt-1 text-[18px] font-black text-slate-950">{ADMIN_SPOMOVE_LIBRARY.length}개</p>
            </div>
            <div className="rounded-lg border border-emerald-100 bg-emerald-50 p-3">
              <p className="text-[10px] font-black text-emerald-700">Briefing Ready</p>
              <p className="mt-1 text-[18px] font-black text-emerald-950">{briefingReadinessSummary.ready}개</p>
            </div>
            <div className="rounded-lg border border-amber-100 bg-amber-50 p-3">
              <p className="text-[10px] font-black text-amber-700">Needs Editorial</p>
              <p className="mt-1 text-[18px] font-black text-amber-950">{briefingReadinessSummary.needsEditorial}개</p>
            </div>
            <div className="rounded-lg border border-sky-100 bg-sky-50 p-3">
              <p className="text-[10px] font-black text-sky-700">Legacy</p>
              <p className="mt-1 text-[18px] font-black text-sky-950">{briefingReadinessSummary.legacy}개</p>
            </div>
            <div className="rounded-lg border border-slate-200 bg-white p-3">
              <p className="text-[10px] font-black text-slate-500">Missing</p>
              <p className="mt-1 text-[18px] font-black text-slate-950">{briefingReadinessSummary.missing}개</p>
            </div>
          </div>
          <div className="mt-2 grid gap-2 sm:grid-cols-3">
            <div className="rounded-lg border border-emerald-100 bg-emerald-50/70 p-3">
              <p className="text-[10px] font-black text-emerald-700">Source Current</p>
              <p className="mt-1 text-[18px] font-black text-emerald-950">{sourceIntegritySummary.current}개</p>
            </div>
            <div className="rounded-lg border border-orange-100 bg-orange-50 p-3">
              <p className="text-[10px] font-black text-orange-700">Review Required</p>
              <p className="mt-1 text-[18px] font-black text-orange-950">{sourceIntegritySummary.changed}개</p>
            </div>
            <div className="rounded-lg border border-slate-200 bg-slate-50 p-3">
              <p className="text-[10px] font-black text-slate-500">Source Untracked</p>
              <p className="mt-1 text-[18px] font-black text-slate-950">{sourceIntegritySummary.untracked}개</p>
            </div>
          </div>
          <div className="mt-4 rounded-lg border border-slate-200 bg-slate-50 p-3">
            <div className="flex flex-col gap-2 sm:flex-row sm:items-center sm:justify-between">
              <label className="relative min-w-0 flex-1">
                <span className="sr-only">SPOMOVE 활동 검색</span>
                <Search className="pointer-events-none absolute left-3 top-1/2 h-4 w-4 -translate-y-1/2 text-slate-400" aria-hidden />
                <input value={searchQuery} onChange={(event) => setSearchQuery(event.target.value)} placeholder="활동명, 프리셋 ID, 태그 검색" className="h-9 w-full rounded-lg border border-slate-200 bg-white pl-9 pr-3 text-[12px] font-semibold outline-none focus:border-indigo-400" />
              </label>
              <div className="flex shrink-0 gap-1.5">
                <button type="button" onClick={() => setExpandedPresetId(null)} className="h-9 rounded-lg border border-slate-200 bg-white px-3 text-[11px] font-black text-slate-600 hover:text-indigo-700">모두 접기</button>
                <button type="button" onClick={() => setExpandedPresetId('__all__')} className="h-9 rounded-lg border border-slate-200 bg-white px-3 text-[11px] font-black text-slate-600 hover:text-indigo-700">모두 펼치기</button>
              </div>
            </div>
            <div className="flex flex-col gap-2 sm:flex-row sm:items-center sm:justify-between">
              <p className="text-[11px] font-black text-slate-600">작업 필터</p>
              <p className="text-[11px] font-bold text-slate-500">현재 {visiblePresetCount}개 프리셋 표시</p>
            </div>
            <div className="mt-2 flex flex-wrap gap-1.5">
              {SPOMOVE_CONTENT_WORK_FILTERS.map((filter) => {
                const active = workFilter === filter.id;
                return (
                  <button
                    key={filter.id}
                    type="button"
                    onClick={() => setWorkFilter(filter.id)}
                    className={`h-8 rounded-full border px-3 text-[11px] font-black ${
                      active
                        ? 'border-indigo-500 bg-indigo-50 text-indigo-700'
                        : 'border-slate-200 bg-white text-slate-500'
                    }`}
                  >
                    {filter.label}
                    <span className="ml-1 text-[10px] opacity-60">{workFilterCounts[filter.id]}</span>
                  </button>
                );
              })}
            </div>
            <p className="mt-3 text-[11px] font-black text-slate-600">Commercial Briefing Readiness (Admin QA)</p>
            <div className="mt-2 flex flex-wrap gap-1.5">
              {SPOMOVE_BRIEFING_READINESS_FILTERS.map((filter) => {
                const active = workFilter === filter.id;
                return (
                  <button
                    key={filter.id}
                    type="button"
                    onClick={() => setWorkFilter(filter.id)}
                    className={`h-8 rounded-full border px-3 text-[11px] font-black ${
                      active
                        ? 'border-emerald-500 bg-emerald-50 text-emerald-800'
                        : 'border-slate-200 bg-white text-slate-500'
                    }`}
                  >
                    {filter.label}
                    <span className="ml-1 text-[10px] opacity-60">{workFilterCounts[filter.id]}</span>
                  </button>
                );
              })}
            </div>
            <p className="mt-3 text-[11px] font-black text-slate-600">Source Integrity (Admin QA)</p>
            <div className="mt-2 flex flex-wrap gap-1.5">
              {SPOMOVE_SOURCE_INTEGRITY_FILTERS.map((filter) => {
                const active = workFilter === filter.id;
                return (
                  <button
                    key={filter.id}
                    type="button"
                    onClick={() => setWorkFilter(filter.id)}
                    className={`h-8 rounded-full border px-3 text-[11px] font-black ${
                      active
                        ? 'border-orange-500 bg-orange-50 text-orange-800'
                        : 'border-slate-200 bg-white text-slate-500'
                    }`}
                  >
                    {filter.label}
                    <span className="ml-1 text-[10px] opacity-60">{workFilterCounts[filter.id]}</span>
                  </button>
                );
              })}
            </div>
            <p className="mt-3 text-[11px] font-black text-slate-600">결손 빠른 필터</p>
            <div className="mt-2 flex flex-wrap gap-1.5">
              {SPOMOVE_BRIEFING_GAP_FILTERS.map((filter) => {
                const active = workFilter === filter.id;
                return (
                  <button
                    key={filter.id}
                    type="button"
                    onClick={() => setWorkFilter(filter.id)}
                    className={`h-8 rounded-full border px-3 text-[11px] font-black ${
                      active
                        ? 'border-amber-500 bg-amber-50 text-amber-900'
                        : 'border-slate-200 bg-white text-slate-500'
                    }`}
                  >
                    {filter.label}
                    <span className="ml-1 text-[10px] opacity-60">{workFilterCounts[filter.id]}</span>
                  </button>
                );
              })}
            </div>
            <div className="mt-3 flex flex-col gap-2 border-t border-slate-200 pt-3 sm:flex-row sm:items-center sm:justify-between">
              <p className="text-[11px] font-bold leading-4 text-slate-500">
                현재 필터에 보이는 항목만 초안을 채웁니다. 기존 입력값은 덮어쓰지 않고 빈 필드만 보완합니다.
              </p>
              <button
                type="button"
                onClick={fillVisibleStarterDrafts}
                disabled={visiblePresetCount === 0 || loading}
                className="inline-flex h-9 shrink-0 items-center justify-center rounded-lg bg-indigo-600 px-3 text-[12px] font-black text-white shadow-sm hover:bg-indigo-700 disabled:opacity-40"
              >
                보이는 항목 초안 채우기
              </button>
            </div>
          </div>
          {error ? (
            <p className="mt-3 rounded-lg border border-rose-100 bg-rose-50 px-3 py-2 text-[12px] font-bold text-rose-700">
              {error}
            </p>
          ) : null}
          {saveIssues.length > 0 ? (
            <div className="mt-3 rounded-lg border border-amber-200 bg-amber-50 px-3 py-3 text-[12px] text-amber-950">
              <p className="font-black">
                공식 가이드 게시 조건을 통과하지 못한 프리셋 {issuePresetCount}개, 오류 {saveIssues.length}개가 있습니다.
              </p>
              <p className="mt-1 font-semibold leading-5 text-amber-800">
                임시 작성 중인 draft는 저장할 수 있지만, published 상태는 수업에 바로 쓸 수 있는 필수 항목을 모두 채워야 합니다.
              </p>
            </div>
          ) : null}
        </section>

        {loading ? (
          <div className="flex justify-center rounded-xl border border-slate-200 bg-white py-16">
            <div className="h-8 w-8 animate-spin rounded-full border-2 border-indigo-500 border-t-transparent" />
          </div>
        ) : visiblePresetCount === 0 ? (
          <section className="rounded-xl border border-dashed border-slate-200 bg-white px-5 py-10 text-center">
            <p className="text-[15px] font-black text-slate-800">현재 작업 필터에 해당하는 프리셋이 없습니다.</p>
            <p className="mt-2 text-[13px] font-semibold text-slate-500">
              다른 작업 상태를 선택하거나 전체 목록으로 돌아가세요.
            </p>
            <button
              type="button"
              onClick={() => setWorkFilter('all')}
              className="mt-4 rounded-lg border border-slate-200 bg-white px-4 py-2 text-[12px] font-black text-slate-600 hover:text-indigo-700"
            >
              전체 보기
            </button>
          </section>
        ) : (
          SPOMOVE_GROUP_OPTIONS.map((group) => {
            const presets = sortSpomovePresetsByCatalogOrder(
              visibleContentPresets.filter((preset) => preset.programGroup === group.key),
            );
            if (presets.length === 0) return null;

            return (
              <section key={group.key} className="rounded-xl border border-slate-200 bg-white p-4 shadow-sm">
                <div className="flex flex-wrap items-center justify-between gap-2">
                  <div>
                    <h3 className="text-[15px] font-black text-slate-950">{group.label}</h3>
                    <p className="mt-0.5 text-[11px] font-bold text-slate-500">{presets.length}개 프리셋</p>
                  </div>
                </div>

                <div className="mt-4 grid gap-3 lg:grid-cols-2">
                  {presets.map((preset) => {
                    const draft = normalizeContentDraft(draftMap[preset.id]);
                    const briefing = resolveSpomoveBriefingReadiness({
                      preset,
                      contentOverride: draft,
                    });
                    const sourceIntegrity = resolveSpomoveGuideSourceIntegrity({
                      preset,
                      contentOverride: draft,
                    });
                    const briefingGapLabels = [
                      briefing.gaps.missingObjective ? 'objective' : null,
                      briefing.gaps.missingTeachingPoints ? 'teachingPoints' : null,
                      briefing.gaps.missingInstruction ? 'instruction' : null,
                      briefing.gaps.missingFocusTags ? 'focusTags' : null,
                    ].filter(Boolean);

                    return (
                      <button
                        key={preset.id}
                        type="button"
                        onClick={() => { setEditingPresetId(preset.id); setModalTab('guide'); }}
                        className="w-full rounded-lg border border-slate-200 bg-slate-50 p-4 text-left transition-colors hover:border-indigo-300 hover:bg-indigo-50/30"
                      >
                        <div className="flex items-start justify-between gap-3">
                          <div className="min-w-0">
                            <p className="truncate text-[13px] font-black text-slate-950">
                              {['flanker', 'stroop', 'sequential-memory', 'simon'].includes(preset.programGroup)
                                ? getSpomovePresetDisplayModel(preset).displayTitle
                                : draft.displayTitle?.trim() || getSpomovePresetDisplayModel(preset).displayTitle}
                            </p>
                            <p className="mt-1 truncate text-[10px] font-bold text-slate-500">{preset.id}</p>
                            <div className="mt-2 flex flex-wrap gap-1">
                              <span className="rounded-full bg-white px-2 py-0.5 text-[10px] font-black text-emerald-700">
                                {BRIEFING_READINESS_LABELS[briefing.readiness]}
                              </span>
                              <span className={`rounded-full px-2 py-0.5 text-[10px] font-black ${sourceIntegrity.status === 'changed' ? 'bg-orange-50 text-orange-800' : sourceIntegrity.status === 'current' ? 'bg-white text-slate-600' : 'bg-slate-100 text-slate-500'}`}>
                                {SOURCE_INTEGRITY_LABELS[sourceIntegrity.status]}
                              </span>
                              {briefingGapLabels.map((label) => (
                                <span key={label} className="rounded-full bg-amber-50 px-2 py-0.5 text-[10px] font-bold text-amber-800">{label} 없음</span>
                              ))}
                              {(draft.catalogTags ?? []).slice(0, 4).map((tag) => <span key={tag} className="rounded-full bg-white px-2 py-0.5 text-[10px] font-bold text-slate-500">{tag}</span>)}
                            </div>
                          </div>
                          <span className="shrink-0 rounded-full bg-white px-2 py-1 text-[10px] font-black text-indigo-700">편집</span>
                        </div>
                      </button>
                    );
                  })}
                </div>
              </section>
            );
          })
        )}
      </div>
    </main>
    {editingPresetId != null && (() => {
      const preset = ADMIN_SPOMOVE_LIBRARY.find((p) => p.id === editingPresetId);
      if (!preset) return null;
      const draft = liveContentDraft(draftMap, editingPresetId);
      const saved = contentMap[editingPresetId];
      const sourceIntegrity = resolveSpomoveGuideSourceIntegrity({ preset, contentOverride: draft });
      return (
        <SpomoveEditModal
          key={preset.id}
          preset={preset}
          draft={draft}
          saved={saved}
          saving={savingPresetId === editingPresetId}
          deleting={deletingPresetId === editingPresetId}
          tab={modalTab}
          saveIssues={saveIssues}
          sourceIntegrity={sourceIntegrity}
          onTabChange={setModalTab}
          onUpdateDraft={(patch) => updateDraft(editingPresetId, patch)}
          onUpdateMovementGuide={(patch) => updateMovementGuide(editingPresetId, patch)}
          onSave={() => { void saveContent(editingPresetId); }}
          onDelete={() => { void deleteContent(editingPresetId).then(() => setEditingPresetId(null)); }}
          onClose={() => setEditingPresetId(null)}
        />
      );
    })()}
    </>
  );
}

function SpomoveThumbnailManager() {
  const [thumbnailPaths, setThumbnailPaths] = useState<Record<string, string>>({});
  const pathsRef = useRef(thumbnailPaths);
  pathsRef.current = thumbnailPaths;
  const packUpdatedAtRef = useRef<string | null>(null);
  const [cacheBust, setCacheBust] = useState<number | undefined>();
  const [loading, setLoading] = useState(true);
  const [savingPresetId, setSavingPresetId] = useState<string | null>(null);
  const [deletingPresetId, setDeletingPresetId] = useState<string | null>(null);
  const [error, setError] = useState<string | null>(null);

  const load = useCallback(async () => {
    setLoading(true);
    setError(null);
    try {
      const supabase = getSupabaseBrowserClient();
      const { data, error: loadError } = await supabase
        .from('think_asset_packs')
        .select('assets_json, updated_at')
        .eq('id', SPOMOVE_THUMBNAIL_PACK_ID)
        .maybeSingle();

      if (loadError && loadError.code !== 'PGRST116') {
        throw loadError;
      }

      const next = normalizeSpomoveThumbnailMap(data?.assets_json);
      packUpdatedAtRef.current = (data?.updated_at as string | undefined) ?? null;
      setThumbnailPaths(next);
      pathsRef.current = next;
      setCacheBust(resolveSpomovePackCacheBust(data?.updated_at as string | undefined, Object.values(next)));
    } catch (loadError) {
      setError(loadError instanceof Error ? loadError.message : 'SPOMOVE 썸네일을 불러오지 못했습니다.');
    } finally {
      setLoading(false);
    }
  }, []);

  useEffect(() => {
    void load();
  }, [load]);

  const persist = useCallback(async (next: Record<string, string>) => {
    try {
      const body = await saveThinkAssetPack({
        id: SPOMOVE_THUMBNAIL_PACK_ID,
        name: SPOMOVE_THUMBNAIL_PACK_NAME,
        theme: 'spomove',
        assets_json: { thumbnails: next } satisfies SpomoveThumbnailAssetsJson,
        expected_updated_at: packUpdatedAtRef.current,
      });
      packUpdatedAtRef.current = body.updated_at ?? packUpdatedAtRef.current;
      setThumbnailPaths(next);
      pathsRef.current = next;
      setCacheBust(resolveSpomovePackCacheBust(body.updated_at, Object.values(next)) ?? Date.now());
    } catch (saveError) {
      if (saveError instanceof ThinkAssetPackConflictError) {
        const serverMap = normalizeSpomoveThumbnailMap(saveError.body.assets_json);
        setThumbnailPaths(serverMap);
        pathsRef.current = serverMap;
        packUpdatedAtRef.current = saveError.body.updated_at ?? packUpdatedAtRef.current;
        setCacheBust(resolveSpomovePackCacheBust(saveError.body.updated_at, Object.values(serverMap)) ?? Date.now());
      }
      throw saveError;
    }
  }, []);

  const uploadThumbnail = useCallback(async (presetId: string, file: File) => {
    if (!file.type.startsWith('image/')) {
      toast.error('이미지 파일만 업로드할 수 있습니다.');
      return;
    }
    if (file.size > MAX_SETUP_IMAGE_BYTES) {
      toast.error('이미지는 10MB 이하만 업로드할 수 있습니다.');
      return;
    }

    setSavingPresetId(presetId);
    setError(null);
    try {
      const optimized = await optimizeToWebP(file, SPOMOVE_THUMBNAIL_OPTIMIZE);
      const path = spomoveThumbnailPath(presetId, 'webp');
      await uploadToStorage(path, optimized, 'image/webp');

      const previousPath = pathsRef.current[presetId];
      const next = { ...pathsRef.current, [presetId]: path };

      if (previousPath && previousPath !== path) {
        try {
          await deleteFromStorage(previousPath);
        } catch {
          /* Previous thumbnail cleanup failure should not block the replacement. */
        }
      }

      await persist(next);
      const savedKb = Math.max(1, Math.round(optimized.size / 1024));
      toast.success(`SPOMOVE 썸네일을 저장했습니다. (${savedKb}KB)`);
    } catch (uploadError) {
      const message = uploadError instanceof Error ? uploadError.message : 'SPOMOVE 썸네일 저장에 실패했습니다.';
      setError(message);
      toast.error(message);
    } finally {
      setSavingPresetId(null);
    }
  }, [persist]);

  const deleteThumbnail = useCallback(async (presetId: string) => {
    const previousPath = pathsRef.current[presetId];
    if (!previousPath) return;

    setDeletingPresetId(presetId);
    setError(null);
    try {
      try {
        await deleteFromStorage(previousPath);
      } catch {
        /* Storage cleanup can be retried later; keep DB state consistent for the admin UI. */
      }
      const next = { ...pathsRef.current };
      delete next[presetId];
      await persist(next);
      toast.success('SPOMOVE 썸네일을 삭제했습니다.');
    } catch (deleteError) {
      const message = deleteError instanceof Error ? deleteError.message : 'SPOMOVE 썸네일 삭제에 실패했습니다.';
      setError(message);
      toast.error(message);
    } finally {
      setDeletingPresetId(null);
    }
  }, [persist]);

  const savedCount = Object.keys(thumbnailPaths).length;

  return (
    <main className="min-h-[calc(100dvh-73px)] bg-slate-50 p-4 sm:p-6">
      <div className="mx-auto max-w-[1500px] space-y-5">
        <section className="rounded-xl border border-slate-200 bg-white p-5 shadow-sm">
          <div className="flex flex-col gap-3 sm:flex-row sm:items-start sm:justify-between">
            <div>
              <p className="text-[11px] font-black uppercase tracking-[0.12em] text-indigo-600">
                SPOMOVE thumbnails
              </p>
              <h2 className="mt-1 text-[18px] font-black text-slate-950">SPOMOVE 공식 프리셋 썸네일</h2>
              <p className="mt-1 text-[12px] font-semibold leading-5 text-slate-500">
                공개 공식 프리셋 {ADMIN_SPOMOVE_LIBRARY.length}개의 썸네일만 관리합니다. SPOMAT 2×2 패드와 맞추려면 1:1 정사각형으로 업로드하세요.
              </p>
            </div>
            <button
              type="button"
              onClick={() => void load()}
              disabled={loading}
              className="inline-flex h-10 shrink-0 items-center justify-center gap-2 rounded-lg border border-slate-200 bg-white px-4 text-[12px] font-black text-slate-700 disabled:opacity-50"
            >
              <RefreshCw size={14} className={loading ? 'animate-spin' : ''} />
              새로고침
            </button>
          </div>
          <div className="mt-4 grid gap-2 sm:grid-cols-3">
            <div className="rounded-lg bg-slate-50 p-3">
              <p className="text-[10px] font-black text-slate-500">공식 프리셋</p>
              <p className="mt-1 text-[18px] font-black text-slate-950">{ADMIN_SPOMOVE_LIBRARY.length}개</p>
            </div>
            <div className="rounded-lg bg-indigo-50 p-3">
              <p className="text-[10px] font-black text-indigo-600">저장된 썸네일</p>
              <p className="mt-1 text-[18px] font-black text-indigo-900">{savedCount}개</p>
            </div>
            <div className="rounded-lg bg-emerald-50 p-3">
              <p className="text-[10px] font-black text-emerald-700">저장 위치</p>
              <p className="mt-1 text-[12px] font-black text-emerald-900">think_asset_packs</p>
            </div>
          </div>
          {error ? (
            <p className="mt-3 rounded-lg border border-rose-100 bg-rose-50 px-3 py-2 text-[12px] font-bold text-rose-700">
              {error}
            </p>
          ) : null}
        </section>

        {loading ? (
          <div className="flex justify-center rounded-xl border border-slate-200 bg-white py-16">
            <div className="h-8 w-8 animate-spin rounded-full border-2 border-indigo-500 border-t-transparent" />
          </div>
        ) : (
          SPOMOVE_GROUP_OPTIONS.map((group) => {
            const presets = sortSpomovePresetsByCatalogOrder(
              ADMIN_SPOMOVE_LIBRARY.filter((preset) => preset.programGroup === group.key),
            );

            return (
              <section key={group.key} className="rounded-xl border border-slate-200 bg-white p-4 shadow-sm">
                <div className="flex flex-wrap items-center justify-between gap-2">
                  <div>
                    <h3 className="text-[15px] font-black text-slate-950">{group.label}</h3>
                    <p className="mt-0.5 text-[11px] font-bold text-slate-500">
                      {presets.length}개 / 기준 {group.expectedCount}개
                    </p>
                  </div>
                  {presets.length !== group.expectedCount ? (
                    <span className="rounded-full bg-amber-50 px-2.5 py-1 text-[11px] font-black text-amber-700">
                      기준 개수 확인 필요
                    </span>
                  ) : null}
                </div>

                <div className="mt-4 grid grid-cols-2 gap-3 sm:grid-cols-3 md:grid-cols-4 lg:grid-cols-5 xl:grid-cols-6">
                  {presets.map((preset) => {
                    const path = thumbnailPaths[preset.id] ?? '';
                    const imageUrl = resolveSpomoveThumbnailUrl(path, cacheBust);
                    const savingThis = savingPresetId === preset.id;
                    const deletingThis = deletingPresetId === preset.id;

                    return (
                      <article key={preset.id} className="overflow-hidden rounded-lg border border-slate-200 bg-slate-50">
                        <div className="relative aspect-square overflow-hidden border-b border-slate-200 bg-white">
                          {imageUrl ? (
                            <img src={imageUrl} alt={`${preset.title} 썸네일`} className="h-full w-full object-cover" />
                          ) : (
                            <div className="grid h-full w-full place-items-center bg-slate-100 text-slate-400">
                              <ImageIcon size={24} />
                            </div>
                          )}
                        </div>
                        <div className="p-3">
                          <p className="line-clamp-2 text-[12px] font-black leading-4 text-slate-950">{getSpomovePresetDisplayModel(preset).displayTitle}</p>
                          <p className="mt-1 truncate text-[10px] font-bold text-slate-500">{preset.id}</p>
                          {path ? (
                            <p className="mt-2 truncate text-[10px] font-semibold text-slate-400">{path}</p>
                          ) : (
                            <p className="mt-2 text-[10px] font-semibold text-slate-400">썸네일 없음</p>
                          )}

                          <div className="mt-3 flex flex-wrap items-center gap-1.5">
                            <label className="spm-btn-primary inline-flex h-8 flex-1 cursor-pointer items-center justify-center rounded-[10px] px-2 text-[11px] font-black focus-visible:outline-none has-[:disabled]:cursor-not-allowed has-[:disabled]:opacity-50">
                              {savingThis ? (
                                <Loader2 size={13} className="mr-1 animate-spin" />
                              ) : null}
                              {path ? '교체' : '업로드'}
                              <input
                                type="file"
                                accept="image/*"
                                disabled={savingThis || deletingThis}
                                className="sr-only"
                                onChange={async (event) => {
                                  const file = event.target.files?.[0];
                                  if (file) await uploadThumbnail(preset.id, file);
                                  event.target.value = '';
                                }}
                              />
                            </label>
                            <button
                              type="button"
                              onClick={() => void deleteThumbnail(preset.id)}
                              disabled={!path || savingThis || deletingThis}
                              className="inline-flex h-8 items-center justify-center rounded-lg border border-slate-200 bg-white px-2 text-[11px] font-black text-rose-600 disabled:opacity-40"
                              aria-label={`${preset.title} 썸네일 삭제`}
                            >
                              {deletingThis ? <Loader2 size={13} className="animate-spin" /> : <Trash2 size={13} />}
                            </button>
                          </div>
                        </div>
                      </article>
                    );
                  })}
                </div>
              </section>
            );
          })
        )}
      </div>
    </main>
  );
}

function SpomoveGuideVideoManager() {
